transforms.result:
.shelf-panel {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  padding: 0.75rem;
}
.shelf-search {
  position: sticky;
  top: 0;
  z-index: 5;
}
.search-input {
  width: 100%;
  padding: 0.5rem 0.75rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  font-size: 0.75rem;
  font-family: inherit;
  background: #fff;
  color: #334155;
  outline: none;
}
.search-input:focus { border-color: #10b981; }
.pending-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: linear-gradient(135deg, #ecfdf5, #d1fae5);
  border: 1px solid #a7f3d0;
  border-radius: 0.5rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: #065f46;
}
.cancel-btn {
  background: #fff;
  border: 1px solid #6ee7b7;
  border-radius: 0.35rem;
  padding: 0.15rem 0.4rem;
  font-size: 0.65rem;
  cursor: pointer;
  color: #065f46;
}
.category-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}
.cat-btn {
  padding: 0.35rem 0.6rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.4rem;
  background: #fff;
  font-size: 0.65rem;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
  transition: all 0.15s;
}
.cat-btn:hover { background: #f1f5f9; }
.cat-btn.active {
  background: #10b981;
  color: #fff;
  border-color: #10b981;
}
.shelf-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}
.selected-detail {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  padding: 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.72rem;
}
.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.detail-row span:first-child { color: #64748b; }
.detail-row span:last-child, .detail-row b { color: #334155; font-weight: 700; }
.detail-formula {
  font-family: monospace;
  font-size: 0.65rem;
  color: #64748b;
  font-weight: 400;
}
.state-tag {
  font-size: 0.6rem;
  padding: 0.1rem 0.35rem;
  background: #f1f5f9;
  border-radius: 0.25rem;
  color: #475569;
}
.detail-desc {
  font-size: 0.65rem;
  color: #475569;
  background: #f8fafc;
  padding: 0.35rem 0.5rem;
  border-radius: 0.3rem;
  margin-top: 0.2rem;
}

